<?php $logs=rows('SELECT a.*,u.username FROM audit_log a LEFT JOIN admin_users u ON u.id=a.user_id ORDER BY a.id DESC LIMIT 200');$actionNames=['login'=>'Вход','logout'=>'Выход','save'=>'Сохранение','delete'=>'Удаление','upload'=>'Загрузка','export'=>'Выгрузка','download'=>'Скачивание','status'=>'Изменение статуса','retry_mail'=>'Повторная отправка','password_change'=>'Изменение пароля']; ?>
<section class="admin-panel"><h2>Последние 200 действий</h2><div class="table-scroll"><table class="admin-table"><thead><tr><th>Дата</th><th>Администратор</th><th>Действие</th><th>Раздел</th><th>Запись</th></tr></thead><tbody><?php foreach($logs as $a): ?><tr><td><?= e($a['created_at']) ?></td><td><?= e($a['username']??'—') ?></td><td><?= e($actionNames[$a['action']]??$a['action']) ?></td><td><?= e($a['entity']) ?></td><td><?= e($a['entity_id']) ?></td></tr><?php endforeach ?><?php if(!$logs): ?><tr><td colspan="5">Действий пока нет.</td></tr><?php endif ?></tbody></table></div></section>
